const a={meta:{title:"POP · Studio dla twórców Fortnite"},nav:{features:"Funkcje",boussole:"Boussole",pricing:"Cennik",faq:"FAQ",login:"Zaloguj się",join:"Dołącz do bety",home:"POP, strona główna",lang:"Język",search:"Szukaj kraju"},hero:{announce:"Nowość: Boussole, wbudowany asystent",h1a:"Twoje mapy Fortnite.",h1b:"Razem. Bez chaosu.",subA:"POP zbiera całe studio UEFN w jednym miejscu: ",subB:"zadania na godzinę",subC:", Verse połączony z UEFN, tablica, analiza rynku i podział zarobków.",cta:"Dołącz do listy oczekujących",see:"Zobacz funkcje",micro1:"Zamknięta beta",micro2:"Dostęp z listy oczekujących",micro3:"Połączony z UEFN"},marquee:{label:"Działa z twoimi narzędziami",epic:"API Fortnite od Epic"},pain:{eyebrow:"Problem",h2a:"Discord, trzy Google Docs,",h2b:"i nikt nie wie, kto co robi.",without:"Bez POP",with:"Z POP",bad:["„Kto ruszał spawner?”","Verse krąży po Discordzie w .txt","Lista zadań w Google Doc","Arkusz zarobków, wersja 7","„To kiedy w końcu wydajemy?”","Budujemy, nie wiedząc, czy gatunek działa"],good:["Każda akcja jest zapisana i odwracalna","Ctrl+S wysyła Verse do UEFN","Zadania na godzinę, z zależnościami","Jasne zestawienie dla każdego","Boussole śledzi kamienie milowe i opóźnienia","Werdykt dla każdego gatunku, na prawdziwych danych"]},feat:{eyebrow:"Funkcje",h2:"Całe studio, od pomysłu do premiery.",p:"To, co tu widzisz, to prawdziwe ekrany POP, w uproszczeniu.",items:[{tag:"Zadania i Boussole",h:"Zadania na godzinę. Asystent każdego ranka.",p:"Generator dzieli mapę na zadania na godzinę, z zależnościami. Boussole podsumowuje dzień, zgłasza opóźnienia i podpowiada, od czego zacząć.",pts:["Kanban i zależności","Śledzenie opóźnień i kamieni milowych","„Weź” jednym kliknięciem"]},{tag:"Edytor Verse",h:"Ctrl+S i już jest w UEFN.",p:"Verse piszesz w POP, a trafia prosto do projektu: kompilacja, błędy we właściwej linii, sesja testowa. Asystent wyjaśnia i poprawia, bez zewnętrznych usług.",pts:["Kompilacja w UEFN","Błędy w linii","Proponowane poprawki"]},{tag:"Organizer",h:"Wszystkie urządzenia. Uporządkowane w trzy sekundy.",p:"Szukaj po tagu, typie lub folderze, zaznacz dwadzieścia i zmień nazwę, przenieś lub zduplikuj za jednym razem. Ctrl+Z cofa. Gdy UEFN jest zamknięty, zmiany czekają.",pts:["Wyszukiwanie tag:, type:, folder:","Zmiany zbiorcze","Wszystko można cofnąć"]},{tag:"Tablica",h:"Rysujcie mapę razem.",p:"Karteczki, kształty, strzałki, kolory, pogrubienie, podkreślenie: wszystko, by rozpisać pomysły. Głosujcie, a najlepsze karteczki zamieńcie w zadania.",pts:["Pełne formatowanie","Współpraca na żywo","Karteczki → zadania"]},{tag:"Analiza",h:"Wiedz, co budować, zanim zaczniesz.",p:"Które gatunki przyciągają graczy, gdzie jest miejsce, które mapy startują od premiery i co jest hitem w wideo. Dane z oficjalnego API Epic.",pts:["Werdykt dla gatunku","Mapy, które działają","Trendy TikTok i Shorts"]},{tag:"Wypłaty",h:"Każdy wie, ile zarabia.",p:"Zasady podziału procentowe, stałe lub za zadanie, import zarobków, zestawienie dla każdej osoby. Koniec z arkuszem zgubionym na Discordzie.",pts:["Procent, stała kwota, za zadanie","Import CSV","Zestawienie dla każdego"]}],aiB:"Masz już AI?",aiText:"Połącz Claude, Cursor, Codex lub inne AI zgodne z MCP: bierze zadanie, pisze Verse, kompiluje i zamyka zadanie z notatką. Każda akcja jest zapisana i odwracalna."},bou:{eyebrow:"Wbudowany asystent",h2a:"Zadaj pytanie.",h2b:"Boussole odpowie.",p:"Boussole zna twoje zadania, kamienie milowe i zespół. Mówi, co jest opóźnione, kto nad czym pracuje i od czego zacząć, a nowych użytkowników prowadzi krok po kroku. Twoje dane nie opuszczają POP.",sub:"wbudowany asystent",ask:"Jak mam…?",demo:[{q:"Co mam teraz zrobić?",a:["**Cześć Léa, nadrabiamy zaległości?**","[r] 2 zadania są opóźnione.","[g] Wczoraj ukończyłaś 3 zadania.","Teraz: **#42 System punktów**, który odblokowuje 3 inne zadania."]},{q:"Jak połączyć UEFN?",a:["**Jak połączyć UEFN z POP?**","1. Organizer → Pobierz UEFN Link.","2. Kliknij dwukrotnie pop-link.exe na PC.","3. W UEFN: Model Context Protocol → Start Server."]},{q:"Czy zdążymy na betę?",a:["[o] Kamień milowy „Beta” za 5 dni: zostało 9 zadań.","W obecnym tempie (1,5 dziennie) zajmie to 6 dni. **Przewidywane opóźnienie: 1 dzień.**"]},{q:"Nad czym pracuje Hugo?",a:["**Hugo** ma 1 zadanie w toku i 2 do zrobienia:","• **#38** Scenografia strefy 2 · w toku od wczoraj","• **#44** Ekran końcowy · czeka na #42","[g] 4 zadania ukończone w tym tygodniu."]},{q:"Czy moje AI może zamykać zadania?",a:["Tak: po połączeniu w „Połączone AI” używa **next_task**, **set_task_status** i **comment_task**. Każda akcja jest oznaczona „AI” w historii."]}]},stats:[["1 h","na zadanie, by codziennie iść do przodu"],["0","wymaganych zewnętrznych usług AI"],["7 dni","statystyk na mapę, z API Epic"],["100%","akcji w UEFN do cofnięcia"]],pricing:{eyebrow:"Cennik",h2:"Wybierz plan.",p:"POP jest w zamkniętej becie: dostęp przez listę oczekujących. Ceny obowiązują od startu, a przed każdą płatnością dostaniesz powiadomienie.",perMonth:"/ mies.",compare:"Porównaj plany",unlimited:"Bez limitu",soon:"Wkrótce",plans:[{name:"Twórca",tag:"Na start",desc:"Jedna mapa, mały zespół, wszystko, co najważniejsze.",cta:"Dołącz do listy"},{name:"Studio",tag:"Najpełniejszy",desc:"Dla studiów, które wydają mapy zespołowo.",cta:"Dołącz do listy"},{name:"Studio+",tag:"Wkrótce",desc:"Wszystko ze Studio plus POP Forge: aplikacja desktopowa, która buduje w UEFN.",cta:"Dołącz do listy"}],rows:["Organizacja","Zadania na godzinę, Kanban, zależności","Boussole, wbudowany asystent","Strony, tablica, planowanie i kamienie milowe","Mapy","Członkowie","UEFN","UEFN Link: zsynchronizowane projekty","Połączony edytor Verse (kompilacja, błędy w linii)","Organizer aktorów i zmiany zbiorcze","Połączone AI (Claude, Cursor, Codex…)","POP Forge: wspomagane budowanie w UEFN","Rozwój","Analiza rynku i mapy, które działają","Trendy wideo TikTok i YouTube Shorts","Wymiana playtestów i dzień premiery","Podział zarobków i zestawienia","Discord, GitHub, Lore"]},faq:{eyebrow:"FAQ",h2:"Pytania, które słyszymy.",items:[["Czy potrzebuję PC z Windows?","Do połączenia z UEFN tak: UEFN działa tylko na Windows, a UEFN Link uruchamia się na tym PC. Reszta POP działa w każdej przeglądarce, także na Macu."],["Czy POP publikuje moją mapę?","Nie. POP przygotowuje wszystko (kontrola przed publikacją, playtesty, plan dnia premiery), ale publikacja zawsze odbywa się w portalu twórców Epic."],["Jak działa asystent Boussole?","Boussole jest wbudowany w POP: czyta twoje zadania, ich terminy, zależności i kamienie milowe, aby podsumować dzień, odpowiadać na pytania („co jest opóźnione?”, „nad czym pracuje Hugo?”) i wyjaśniać, jak korzystać z POP. Działa w całości w POP: twoje dane nie trafiają do żadnej zewnętrznej usługi."],["A jeśli chcę używać własnego AI?","Połącz Claude, Cursor, Codex lub inne AI zgodne z MCP w „Połączone AI”. Może czytać i edytować zadania, Verse i aktorów UEFN, a każda akcja jest zapisana i odwracalna."],["Skąd pochodzą dane w analizie?","Z oficjalnego API Fortnite od Epic: gracze, szczyt jednoczesnych graczy, czas gry i retencja każdej publicznej mapy, z 7 dni."],["Jak uzyskać dostęp?","POP jest w zamkniętej becie. Dołącz do listy oczekujących: sprawdzamy zgłoszenia pojedynczo, a potem wysyłamy ci login i tymczasowe hasło, które zmienisz przy pierwszym logowaniu."],["Ile to kosztuje?","Ceny są podane wyżej. Obowiązują od otwarcia POP; uczestnicy bety zostaną powiadomieni przed każdą płatnością."]]},final:{h2a:"Twoja następna mapa",h2b:"zaczyna się tutaj.",p:"Dołącz do listy oczekujących: wyślemy ci dostęp, gdy tylko zwolni się miejsce."},foot:{made:"Stworzone przez twórców Fortnite, dla twórców Fortnite.",legal:"Fortnite i UEFN są znakami towarowymi Epic Games. POP nie jest powiązany z Epic Games ani przez nie wspierany.",product:"Produkt",help:"Pomoc",account:"Konto"},mock:{overview:"Przegląd",nav:["Przegląd","Strony","Tablica","Zadania","Edytor Verse","Organizer","Rynek"],hello:"Cześć Léa, proponuję zacząć od #42.",late:"2 zadania opóźnione (najstarsze miało termin 12 lis.).",mile:"Kamień milowy „Beta” za 5 dni: zostało 9 zadań, przewidywane opóźnienie 1 dzień.",take:"Weź",start:"Zacznij",unlocks:"odblokowuje 3 inne zadania",today:"termin dziś",waits:"czeka na #42",todo:"Do zrobienia",doing:"W toku",done:"Zrobione",tasks:["System punktów","Scenografia strefy 2","Ekran końcowy","Wewnętrzny playtest","Spawn graczy","Burza"],sent:"wysłano do UEFN",err:"Linia 12: nie można dodać int i float.",fix:"Popraw: Points += 1",red:"Drużyna czerwona",selected:"2 zaznaczone",rename:"Zmień nazwę",move:"Przenieś",dup:"Duplikuj",s1:"Tryb drużynowy 4v4",s2a:"Boss końcowy",s2b:"na środku",s3:"Ekonomia: 1 moneta / eliminacja",verdicts:["Dobra okazja","Popularny, ale zatłoczony","Nasycony","Nisza"],typical:"graczy / typowa mapa",earnings:"Zarobki z października",roles:["Kod · 40%","Mapa · 35%","Muzyka · stała","Reszta"],noTransfer:"POP liczy, nigdy nie przelewa pieniędzy."},wl:{eyebrow:"Zamknięta beta",title:"Dołącz do listy oczekujących",intro:"Otwieramy POP stopniowo, by zadbać o każde studio. Powiedz nam, kim jesteś, a wyślemy ci dostęp jak najszybciej.",pageIntro:"W czasie bety konta POP zakłada zespół. Powiedz nam, kim jesteś: po zatwierdzeniu dostępu otrzymasz login i tymczasowe hasło.",invalid:"Ten link dostępu jest nieprawidłowy, już użyty lub wygasł. Złóż prośbę ponownie albo napisz do zespołu POP.",name:"Imię lub pseudonim",email:"E-mail",studio:"Studio",optional:"(opcjonalnie)",studioPh:"Nazwa studia",team:"Wielkość zespołu",teams:["Sam","2–3","4–10","Ponad 10"],exp:"Doświadczenie",exps:["Nowy w UEFN","Kilka opublikowanych map","Doświadczony twórca","Profesjonalne studio"],links:"Twoje mapy lub social media",linksPh:"Kody wysp, TikTok, YouTube…",msg:"Co chcesz robić z POP",msgPh:"Np. jesteśmy w 4 osoby przy mapie tycoon i gubimy się między Discordem a Google Docs.",send:"Poproś o dostęp",sending:"Wysyłanie…",nospam:"Bez spamu: piszemy tylko po to, by dać ci dostęp.",okTitle:"Zapisane, dziękujemy!",okText:"Twoja prośba dotarła do zespołu POP. Gdy tylko zwolni się miejsce, wyślemy ci login i tymczasowe hasło.",alreadyTitle:"Jesteś już na liście.",approvedTitle:"Twój dostęp jest już zatwierdzony.",approvedText:"Twoje konto jest gotowe: zespół POP wyśle ci login i tymczasowe hasło. Jeśli nie dotarły, napisz do nas.",close:"Zamknij"}};export{a as default};
